style.css:
@-moz-document domain("google.com") {
/* Force your PNG as the background */
html, body {
    background-image: url("https://i.imgur.com/GiKNlBk.png") !important;
    background-repeat: repeat !important;      /* tile the PNG */
    background-size: auto !important;          /* keep original size */
    background-position: top left !important;  /* start tiling from top left */
    background-color: transparent !important;  /* remove default pink */
}

/* Ensure search box and logo stay above the background */
#main, #hplogo, form[name="f"], #lga {
    position: relative;
    z-index: 1 !important;
}

/* Search box and buttons styling */
input, button {
    background-color: rgba(255, 255, 255, 0.8) !important;
    color: #000 !important;
    border-radius: 10px !important;
    border: 1px solid #FFB3CC !important;
}

#gb, #hplogo {
    z-index: 2 !important;
}
}
